param([Parameter(Mandatory=$true)][string]$Admission,[switch]$ExecutionAuthorized)
# Exactly one frozen ReleaseCPU project-main CPU8 coarse run; no new half, decoder, build or automatic next job.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs';$tag='upl_damp_mid_CPU_coarse_r1';$cache=@{}
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function RawE([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p)) -Force;Need (!$f.PSIsContainer) 'Expected a file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function E([string]$p){$key=([IO.Path]::GetFullPath($p)).ToLowerInvariant();if(!$cache.ContainsKey($key)){$cache[$key]=RawE $p};return $cache[$key]}
function V($rows){foreach($e in @($rows)){Need ($e.path -and $null -ne $e.bytes -and $e.sha256 -match '^[0-9a-fA-F]{64}$') 'Malformed Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting Entry: '+$e.path)}}
function FinalV($rows){$seen=@{};foreach($e in @($rows)){$key=([IO.Path]::GetFullPath($e.path)).ToLowerInvariant();if(!$seen.ContainsKey($key)){$seen[$key]=RawE $e.path};$a=$seen[$key];Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting final Entry: '+$e.path)}}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit actual-run authorization required';Fresh @($folder,$record,$callPath,$log)
$gateE=E $Admission;$gate=J $gateE.path;Need ($gate.stage -ceq 'upl_damp_mid_admission_r1' -and $gate.passed -eq $true -and $gate.physical_acceptance -eq $false -and @($gate.allowed_jobs).Count -eq 1 -and $gate.allowed_jobs[0] -ceq $tag -and @($gate.inputs).Count -gt 0) 'Singleton root admission for this one coarse run required'
$buildE=E (Join-Path $logs 'upl_damp_ReleaseCPU_r2.build.json');$b=J $buildE.path;Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq 'ReleaseCPU' -and $b.source_bindings_unchanged -and $b.exact_object_basename_closure -and $b.objects_include_project_main -and @($b.objects).Count -eq 86 -and @($b.source_snapshot).Count -eq 265 -and @($b.runtime).Count -eq 4) 'Sealed authoritative frozen CPU86/source265 build required'
$project=J $b.project_call.path;Need ($project.direct_native_call -and $project.typed_LASTEXITCODE_captured_immediately -and $project.owned_call_exited -and $project.exit_code -is [int] -and $project.exit_code -eq 0 -and !$project.invocation_failure) 'Original authoritative typed project exit0 required'
$snapshots=@();$live=@{};foreach($p in @($b.source_snapshot)+@($b.documentation_snapshot,$b.case_readme_snapshot)){Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Recorded original/snapshot identity differed as of build';$live[([IO.Path]::GetFullPath($p.original.path)).ToLowerInvariant()]=$true};foreach($p in $b.source_snapshot){$snapshots+=@($p.snapshot)}
foreach($p in @($b.canonical_programs_before)+@($b.runtime|ForEach-Object{$_.original})){$live[([IO.Path]::GetFullPath($p.path)).ToLowerInvariant()]=$true};foreach($e in $gate.inputs){Need (!$live.ContainsKey(([IO.Path]::GetFullPath($e.path)).ToLowerInvariant())) 'Root proof inputs must not lock mutable production/canonical originals'}
$manifestE=E (Join-Path $logs 'upl_damp_mid_r1.inputs.json');$m=J $manifestE.path;Need ($m.stage -ceq 'upl_damp_mid_prepare_r1' -and $m.passed -and $m.prepared -and !$m.physical_acceptance -and !$m.step_candidate_adopted -and $m.source_build.sha256 -ceq $buildE.sha256 -and $m.source_program.sha256 -ceq $b.program.sha256 -and @($m.jobs).Count -eq 1 -and @($m.source_snapshots265).Count -eq 265) 'Own prepared fallback input/build identity required'
$job=$m.jobs[0];$dt=[Math]::Pow(2,-19);$steps=4798782;$end=[double]$steps*$dt
Need ($job.window -ceq 'coarse' -and $job.backend -ceq 'CPU' -and $job.threads -eq 8 -and $job.dt_s -eq $dt -and $job.steps -eq $steps -and $job.expected_samples -eq 1746 -and @($job.saved_clock_table).Count -eq 1746 -and $job.damping -eq 1 -and $job.damping_coef -eq 0.02 -and $job.inverse_DOM_exact -and $job.only_TimeMax_and_fifth_timeout_changed -and !$job.initial_particle_fields_rewritten -and !$job.step_candidate_adopted -and $job.planned_original_prefix_samples -eq 1469 -and !$job.actual_prefix_proved -and $job.event_completed_step -eq 5243 -and $job.event_part -eq 203) 'Locked fallback coarse/material declaration differs'
foreach($e in $snapshots){Need (@($m.source_snapshots265|Where-Object{$_.path -ieq $e.path -and $_.bytes -eq $e.bytes -and $_.sha256 -ieq $e.sha256}).Count -eq 1) 'Prepare names another frozen source snapshot'}
$x=New-Object Xml.XmlDocument;$x.Load($job.runtime.path);foreach($item in @(@{path='/case/execution/parameters/parameter[@key="DtIni"]';value=$dt},@{path='/case/execution/parameters/parameter[@key="DtFixed"]';value=$dt},@{path='/case/execution/parameters/parameter[@key="TimeMax"]';value=$end},@{path='/case/execution/special/hydromechanics/HydroMechTopLoadRampTime';value=5243*$dt},@{path='/case/execution/special/hydromechanics/HydroMechDrainageStartTime';value=5243*$dt})){$nodes=$x.SelectNodes($item.path);Need ($nodes.Count -eq 1 -and [double]::Parse($nodes[0].GetAttribute('value'),[Globalization.CultureInfo]::InvariantCulture) -eq $item.value) 'Exact raw XML integer-dyadic clock differs'}
Need ($job.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $job.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97' -and $job.configuration.sha256 -ceq $job.runtime.sha256) 'Unchanged seed/Normals/configuration identity differs'
$runtime=@($b.runtime|ForEach-Object{$_.copy});$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_mid_run_r1.json')),(E (Join-Path $tests 'notes\upl_damp_mid_r1.json')),$gateE,$buildE,$b.project_call,$b.log,$b.binlog,$b.program,$manifestE,$job.configuration,$job.runtime,$job.initial_BI4,$job.normals,$job.source_manifest,$job.source_configuration,$job.source_runtime,$b.documentation_snapshot.snapshot,$b.case_readme_snapshot.snapshot)+@($gate.inputs)+$snapshots+@($b.objects)+$runtime
foreach($e in $bindings){Need (!$live.ContainsKey(([IO.Path]::GetFullPath($e.path)).ToLowerInvariant())) 'Mutable live original accidentally entered long-run bindings'}
V $bindings;$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe'");Need ($active.Count -eq 0) 'Another project solver/helper active; no duplicate launch'
$argv=@('-cpu','-ompthreads:8','-stable','-mdbc_freeslip',$job.input_prefix,$folder,'-dirdataout','data','-svres',('-nsteps:'+$steps))
$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');$saved=$ErrorActionPreference;[IO.File]::WriteAllBytes($log,[byte[]]@());Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $b.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$b.program;target_program=$b.program;arguments=$argv;target_arguments=$argv;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;direct_target_call=$true;physical_acceptance=$false})
# Real typed solver exit is sealed before raw/native-analysis checks; never retry a completed solver automatically.
$runOut=$null;$files=@();$count=0;$loop=$null;$total=$null;$rate=$null;$unchanged=$false
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Actual solver failed; preserve partials'
  $runOut=E (Join-Path $folder 'Run.out');$text=[IO.File]::ReadAllText($runOut.path);Need ($text -match '(?m)^\[Simulation finished\s' -and $text -match 'OpenMP\(Threads:8\)') 'Normal CPU8 completion missing'
  foreach($label in @('Simulation Runtime','Total Runtime')){$v=[regex]::Match($text,('(?m)^'+$label+'[.]+:\s*([0-9.]+)\s+sec[.]\s*$'));Need $v.Success 'Actual runtime diagnostic missing';$seconds=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);if($label -ceq 'Simulation Runtime'){$loop=$seconds}else{$total=$seconds}}
  $v=[regex]::Match($text,'Dynamic soil damping rate: ([0-9.eE+-]+) s\^-1');Need $v.Success 'Actual damping-rate diagnostic missing';$rate=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);Need ($rate -gt 30 -and $rate -lt 32) 'Retained eta.02 candidate differs'
  $raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$count=$raw.Count;$wanted=@(0..1745|ForEach-Object{'Part_{0:D4}.bi4' -f $_});Need ($count -eq 1746 -and !(Compare-Object ($raw.Name|Sort-Object) ($wanted|Sort-Object))) 'Own1746 raw sequence differs'
}catch{$failure=$_.Exception.Message}
try{FinalV $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $count -eq 1746)
Save $record ([ordered]@{stage='upl_damp_mid_run_r1';passed=[bool]$passed;backend='CPU';threads=8;window='coarse';configuration='ReleaseCPU';program=$b.program;source_build=$buildE;source_snapshots265=$snapshots;documentation_snapshot=$b.documentation_snapshot.snapshot;case_readme_snapshot=$b.case_readme_snapshot.snapshot;retained_build_objects=$b.objects;runtime_copies=$runtime;input_manifest=$manifestE;job=$job;admission=$gateE;planned_completed_steps=$steps;planned_end_s=$end;expected_native_frames=1746;locked_runtime_clock_values_verified=$true;call=(E $callPath);inputs=$bindings;files=$files;run_out=$runOut;native_frames=$count;actual_damping_rate_s_inv=$rate;simulation_runtime_s=$loop;total_runtime_s=$total;frozen_build_program_inputs_runtime_unchanged=$unchanged;recorded_original_snapshot_identity_checked=$true;live_production_sources_frozen_by_this_run=$false;live_production_or_canonical_rechecked_after_hours=$false;ancestor_prepare_inputs_recursively_rehashed=$false;independent_final_rehash_performed=$unchanged;public_project_main=$true;fixture_or_Run_override=$false;native_decoder_invoked=$false;planned_original_prefix_samples=1469;actual_prefix_proved=$false;new_half_or_full_admitted=$false;step_candidate_adopted=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Mid actual run rejected; preserve $record, no automatic retry"};Write-Output "One frozen CPU8 mid coarse run sealed: $record"
